// ─────────────────────────────────────────────────────────────────────────
//  06 · two collectors, one pass                                     ★★☆
//  concepts: Collectors.teeing · summingInt + counting · filtering + maxBy
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.stream.*;

class Exercise {

    record Call(String endpoint, boolean ok, int millis) {}

    record Health(long failures, String slowestOk) {}

    /** sum / count in one pass. */
    static long averageCents(List<Integer> prices) {
        return prices.stream().collect(Collectors.teeing(Collectors.summingInt(x -> x), Collectors.counting(), (sum, n) -> sum / n));
    }

    /** How many calls failed, and the endpoint of the slowest successful call ("none" if none succeeded), in one pass. */
    static Health health(List<Call> calls) {
        return calls.stream().collect(Collectors.teeing(
            Collectors.filtering(c -> !c.ok(), Collectors.counting()),
            Collectors.filtering(Call::ok, Collectors.maxBy(Comparator.comparingInt(Call::millis))),
            (failures, slowest) -> new Health(failures, slowest.map(Call::endpoint).orElse("none"))));
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("average of three prices", () ->
            eq(averageCents(List.of(100, 200, 300)), 200));
        test("equal prices average to themselves (boundary)", () ->
            eq(averageCents(List.of(250, 250)), 250));
