import static bootcamp.Check.*;

import java.util.*;
import java.util.stream.*;

class Exercise {

    record Post(String author, List<String> tags, int likes) {}

    /** Author → every tag they used. */
    static TreeMap<String, Set<String>> tagsByAuthor(List<Post> ps) {
        return ps.stream().collect(Collectors.groupingBy(Post::author, TreeMap::new, Collectors.flatMapping(p -> p.tags().stream(), Collectors.toSet())));
